ee:message.ee:set-payload:
%dw 2.0 output application/json
var firstRow = payload[0] ---
{ orderId: vars.orderId, status: firstRow.status, customerId: firstRow.customer_id, totalAmount: firstRow.total_amount, currency: firstRow.currency, items: payload map ((row, index) -> { productId: row.sku, name: row.name, sku: row.sku, quantity: row.quantity, unitPrice: row.unit_price, totalPrice: row.total_price }), createdAt: firstRow.created_at, updatedAt: firstRow.updated_at }
